#!/usr/bin/env bash
set -e
echo "=============================================="
echo "🚀 Deploying High-Performance Go Server on VPS"
echo "=============================================="

mkdir -p /opt/ramppulse/server_go
cd /opt/ramppulse

python3 - << "PYEOF"
import zlib, base64, pathlib
p_server_go_go_mod = "eJwVyUESgyAMBdC1OQXLdtEwyPRAin+QaWg0gL1+x7d9VbchcLbU4xjS8GqwC0aU1QWeZyLDOYrBPWjKpe9j5aTVZ7Uisvgf1qbpg+6uwG+ONFXdYN/Eatm3U0rHXTFyoCf9AUkuJDA="
p = pathlib.Path("server_go/go.mod")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_go_mod)))
print("[+] server_go/go.mod written successfully")
p_server_go_auth_go = ""
p = pathlib.Path("server_go/auth.go")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_auth_go)))
print("[+] server_go/auth.go written successfully")
p_server_go_chat_go = ""
p = pathlib.Path("server_go/chat.go")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_chat_go)))
print("[+] server_go/chat.go written successfully")
p_server_go_engine_go = ""
p = pathlib.Path("server_go/engine.go")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_engine_go)))
print("[+] server_go/engine.go written successfully")
p_server_go_ws_go = ""
p = pathlib.Path("server_go/ws.go")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_ws_go)))
print("[+] server_go/ws.go written successfully")
p_server_go_main_go = ""
p = pathlib.Path("server_go/main.go")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(zlib.decompress(base64.b64decode(p_server_go_main_go)))
print("[+] server_go/main.go written successfully")
PYEOF

echo "[1/4] Checking Go toolchain..."
if ! command -v go &>/dev/null; then
    echo "Installing Go (golang-go)..."
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -y && apt-get install -y golang-go git
fi
go version

echo "[2/4] Compiling Go server binary..."
cd /opt/ramppulse/server_go
go mod tidy
CGO_ENABLED=0 go build -ldflags="-s -w" -o /opt/ramppulse/ramppulse-server .
chmod +x /opt/ramppulse/ramppulse-server
ls -lh /opt/ramppulse/ramppulse-server

echo "[3/4] Configuring systemd service..."
cat << "SVCEOF" > /etc/systemd/system/ramppulse.service
[Unit]
Description=RampPulse Go Airport Dispatch Server
After=network.target

[Service]
Type=simple
User=root
WorkingDirectory=/opt/ramppulse
ExecStart=/opt/ramppulse/ramppulse-server
Restart=always
RestartSec=3
Environment="PORT=8000"
Environment="DB_FILE=/opt/ramppulse/dispatch.db"
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
SVCEOF

systemctl daemon-reload
systemctl restart ramppulse
sleep 1

echo "[4/4] Verifying Go server..."
systemctl is-active ramppulse
curl -s http://127.0.0.1:8000/healthz
echo ""
curl -s "http://127.0.0.1:8000/api/users/search?q=orlov" | head -c 200
echo ""
echo "=============================================="
echo "✅ RampPulse Go Server is active and running!"
echo "=============================================="